{"_id":"6ae21610aa85985ef6a55a12","id":"sensenova/SenseNova-Loop-9B-Preview","private":false,"pipeline_tag":"image-text-to-text","library_name":"transformers","tags":["transformers","safetensors","sensenova_loop","text-generation","multimodal","image-text-to-text","looped-transformer","mhc","custom_code","conversational","en","zh","license:apache-2.0","region:us"],"downloads":927,"likes":140,"modelId":"sensenova/SenseNova-Loop-9B-Preview","author":"sensenova","sha":"eda5d06eec244f9bb078fd193255fc615720a1f9","lastModified":"2026-11-01T09:33:28.000Z","gated":false,"disabled":false,"widgetData":[{"text":"Hi, what can you help me with?"},{"text":"What is 84 * 3 / 2?"},{"text":"Tell me an interesting fact about the universe!"},{"text":"Explain quantum computing in simple terms."}],"model-index":null,"config":{"architectures":["SenseNovaLoopForConditionalGeneration"],"auto_map":{"AutoConfig":"modeling_sensenova_loop.SenseNovaLoopConfig","AutoModel":"modeling_sensenova_loop.SenseNovaLoopModel","AutoModelForCausalLM":"modeling_sensenova_loop.SenseNovaLoopForConditionalGeneration","AutoModelForImageTextToText":"modeling_sensenova_loop.SenseNovaLoopForConditionalGeneration"},"model_type":"sensenova_loop","tokenizer_config":{"bos_token":null,"eos_token":"<|im_end|>","unk_token":null,"pad_token":"<|endoftext|>"},"chat_template_jinja":"{%- set image_count = namespace(value=0) %}
{%- set video_count = namespace(value=0) %}
{%- macro render_content(content, do_vision_count, is_system_content=false) %}
    {%- if content is string %}
        {{- content }}
    {%- elif content is iterable and content is not mapping %}
        {%- for item in content %}
            {%- if 'image' in item or 'image_url' in item or item.type == 'image' %}
                {%- if is_system_content %}
                    {{- raise_exception('System message cannot contain images.') }}
                {%- endif %}
                {%- if do_vision_count %}
                    {%- set image_count.value = image_count.value + 1 %}
                {%- endif %}
                {%- if add_vision_id %}
                    {{- 'Picture ' ~ image_count.value ~ ': ' }}
                {%- endif %}
                {{- '<|vision_start|><|image_pad|><|vision_end|>' }}
            {%- elif 'video' in item or item.type == 'video' %}
                {%- if is_system_content %}
                    {{- raise_exception('System message cannot contain videos.') }}
                {%- endif %}
                {%- if do_vision_count %}
                    {%- set video_count.value = video_count.value + 1 %}
                {%- endif %}
                {%- if add_vision_id %}
                    {{- 'Video ' ~ video_count.value ~ ': ' }}
                {%- endif %}
                {{- '<|vision_start|><|video_pad|><|vision_end|>' }}
            {%- elif 'text' in item %}
                {{- item.text }}
            {%- else %}
                {{- raise_exception('Unexpected item type in content.') }}
            {%- endif %}
        {%- endfor %}
    {%- elif content is none or content is undefined %}
        {{- '' }}
    {%- else %}
        {{- raise_exception('Unexpected content type.') }}
    {%- endif %}
{%- endmacro %}
{%- if not messages %}
    {{- raise_exception('No messages provided.') }}
{%- endif %}
{%- if tools and tools is iterable and tools is not mapping %}
    {{- '<|im_start|>system\n' }}
    {{- "# Tools\n\nYou have access to the following functions:\n\n<tools>" }}
    {%- for tool in tools %}
        {{- "\n" }}
        {{- tool | tojson }}
    {%- endfor %}
    {{- "\n</tools>" }}
    {{- '\n\nIf you choose to call a function ONLY reply in the following format with NO suffix:\n\n<tool_call>\n<function=example_function_name>\n<parameter=example_parameter_1>\nvalue_1\n</parameter>\n<parameter=example_parameter_2>\nThis is the value for the second parameter\nthat can span\nmultiple lines\n</parameter>\n</function>\n</tool_call>\n\n<IMPORTANT>\nReminder:\n- Function calls MUST follow the specified format: an inner <function=...></function> block must be nested within <tool_call></tool_call> XML tags\n- Required parameters MUST be specified\n- You may provide optional reasoning for your function call in natural language BEFORE the function call, but NOT after\n- If there is no function call available, answer the question like normal with your current knowledge and do not tell the user about function calls\n</IMPORTANT>' }}
    {%- if messages[0].role == 'system' %}
        {%- set content = render_content(messages[0].content, false, true)|trim %}
        {%- if content %}
            {{- '\n\n' + content }}
        {%- endif %}
    {%- endif %}
    {{- '<|im_end|>\n' }}
{%- else %}
    {%- if messages[0].role == 'system' %}
        {%- set content = render_content(messages[0].content, false, true)|trim %}
        {{- '<|im_start|>system\n' + content + '<|im_end|>\n' }}
    {%- endif %}
{%- endif %}
{%- set ns = namespace(multi_step_tool=true, last_query_index=messages|length - 1) %}
{%- for message in messages[::-1] %}
    {%- set index = (messages|length - 1) - loop.index0 %}
    {%- if ns.multi_step_tool and message.role == "user" %}
        {%- set content = render_content(message.content, false)|trim %}
        {%- if not(content.startswith('<tool_response>') and content.endswith('</tool_response>')) %}
            {%- set ns.multi_step_tool = false %}
            {%- set ns.last_query_index = index %}
        {%- endif %}
    {%- endif %}
{%- endfor %}
{%- if ns.multi_step_tool %}
    {{- raise_exception('No user query found in messages.') }}
{%- endif %}
{%- for message in messages %}
    {%- set content = render_content(message.content, true)|trim %}
    {%- if message.role == "system" %}
        {%- if not loop.first %}
            {{- raise_exception('System message must be at the beginning.') }}
        {%- endif %}
    {%- elif message.role == "user" %}
        {{- '<|im_start|>' + message.role + '\n' + content + '<|im_end|>' + '\n' }}
    {%- elif message.role == "assistant" %}
        {%- set reasoning_content = '' %}
        {%- if message.reasoning_content is string %}
            {%- set reasoning_content = message.reasoning_content %}
        {%- else %}
            {%- if '</think>' in content %}
                {%- set reasoning_content = content.split('</think>')[0].rstrip('\n').split('<think>')[-1].lstrip('\n') %}
                {%- set content = content.split('</think>')[-1].lstrip('\n') %}
            {%- endif %}
        {%- endif %}
        {%- set reasoning_content = reasoning_content|trim %}
        {%- if loop.index0 > ns.last_query_index %}
            {{- '<|im_start|>' + message.role + '\n<think>\n' + reasoning_content + '\n</think>\n\n' + content }}
        {%- else %}
            {{- '<|im_start|>' + message.role + '\n' + content }}
        {%- endif %}
        {%- if message.tool_calls and message.tool_calls is iterable and message.tool_calls is not mapping %}
            {%- for tool_call in message.tool_calls %}
                {%- if tool_call.function is defined %}
                    {%- set tool_call = tool_call.function %}
                {%- endif %}
                {%- if loop.first %}
                    {%- if content|trim %}
                        {{- '\n\n<tool_call>\n<function=' + tool_call.name + '>\n' }}
                    {%- else %}
                        {{- '<tool_call>\n<function=' + tool_call.name + '>\n' }}
                    {%- endif %}
                {%- else %}
                    {{- '\n<tool_call>\n<function=' + tool_call.name + '>\n' }}
                {%- endif %}
                {%- if tool_call.arguments is defined %}
                    {%- for args_name, args_value in tool_call.arguments|items %}
                        {{- '<parameter=' + args_name + '>\n' }}
                        {%- set args_value = args_value | tojson | safe if args_value is mapping or (args_value is sequence and args_value is not string) else args_value | string %}
                        {{- args_value }}
                        {{- '\n</parameter>\n' }}
                    {%- endfor %}
                {%- endif %}
                {{- '</function>\n</tool_call>' }}
            {%- endfor %}
        {%- endif %}
        {{- '<|im_end|>\n' }}
    {%- elif message.role == "tool" %}
        {%- if loop.previtem and loop.previtem.role != "tool" %}
            {{- '<|im_start|>user' }}
        {%- endif %}
        {{- '\n<tool_response>\n' }}
        {{- content }}
        {{- '\n</tool_response>' }}
        {%- if not loop.last and loop.nextitem.role != "tool" %}
            {{- '<|im_end|>\n' }}
        {%- elif loop.last %}
            {{- '<|im_end|>\n' }}
        {%- endif %}
    {%- else %}
        {{- raise_exception('Unexpected message role.') }}
    {%- endif %}
{%- endfor %}
{%- if add_generation_prompt %}
    {{- '<|im_start|>assistant\n' }}
    {%- if enable_thinking is defined and enable_thinking is false %}
        {{- '<think>\n\n</think>\n\n' }}
    {%- else %}
        {{- '<think>\n' }}
    {%- endif %}
{%- endif %}"},"cardData":{"license":"apache-2.0","language":["en","zh"],"library_name":"transformers","pipeline_tag":"image-text-to-text","tags":["multimodal","text-generation","image-text-to-text","looped-transformer","mhc","custom_code"]},"transformersInfo":{"auto_model":"AutoModelForCausalLM","custom_class":"modeling_sensenova_loop.SenseNovaLoopForConditionalGeneration","pipeline_tag":"text-generation"},"siblings":[{"rfilename":".gitattributes"},{"rfilename":"README.md"},{"rfilename":"README_CN.md"},{"rfilename":"assets/loop-mhc-overview.jpg"},{"rfilename":"assets/loop9b-architecture.svg"},{"rfilename":"assets/loop9b-benchmark-results.png"},{"rfilename":"chat_template.jinja"},{"rfilename":"config.json"},{"rfilename":"examples/chocolate/chocolate-horizontal.jpg"},{"rfilename":"examples/energy-analysis/energy-analysis.png"},{"rfilename":"examples/iceland/iceland-horizontal-v2.jpg"},{"rfilename":"examples/ink-journey/ink-journey-demo.mp4"},{"rfilename":"examples/ink-journey/ink-journey-preview.gif"},{"rfilename":"examples/moon-simulation/moon-simulation.gif"},{"rfilename":"examples/odyssey/odyssey-preview.gif"},{"rfilename":"examples/teacher-day/teacher-day-horizontal.jpg"},{"rfilename":"generation_config.json"},{"rfilename":"model-00001-of-00008.safetensors"},{"rfilename":"model-00002-of-00008.safetensors"},{"rfilename":"model-00003-of-00008.safetensors"},{"rfilename":"model-00004-of-00008.safetensors"},{"rfilename":"model-00005-of-00008.safetensors"},{"rfilename":"model-00006-of-00008.safetensors"},{"rfilename":"model-00007-of-00008.safetensors"},{"rfilename":"model-00008-of-00008.safetensors"},{"rfilename":"model.safetensors.index.json"},{"rfilename":"modeling_sensenova_loop.py"},{"rfilename":"mtp.safetensors"},{"rfilename":"preprocessor_config.json"},{"rfilename":"processor_config.json"},{"rfilename":"tokenizer.json"},{"rfilename":"tokenizer_config.json"},{"rfilename":"video_preprocessor_config.json"}],"spaces":["fastgpu/vram-and-gpu-cost-calculator","600me/llm-gpu-cost-calculator","600me/rag-web-scraping-cost-calculator","600me/residential-proxy-sticky-session-calculator","600me/ai-saas-stripe-vs-mor-tax-calculator","mrfakename/sensenova-loop-9b","600me/pdf-api-cost-calculator","600me/seo-workflow-tco-calculator"],"createdAt":"2026-10-28T15:34:40.000Z","safetensors":{"parameters":{"F32":9412959856,"BF16":243290624},"total":9656250480},"usedStorage":38204212983}
